INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('b16c434a-cff5-561e-b712-427a584267ae'::uuid, '0f230cb8-80fc-58f7-9526-e1a23b55bfb6'::uuid, 'Installation solaire 12kWc/10kW', 'Ce système photovoltaïque de 12 kWc, raccordé à un onduleur de 10 kW, est conçu pour l’autoconsommation. Il permet à l’utilisateur de produire et consommer directement sa propre électricité solaire, réduisant ainsi sa dépendance au réseau et ses factures d’électricité. Points clés : 90 % des besoins couverts et 23200 Dhs/an d''economies', '["https://lechantier.ma/uploads/media/44e316d91e51.webp", "https://lechantier.ma/uploads/media/ec4b57885a67.webp", "https://lechantier.ma/uploads/media/75450dfe08d6.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/44e316d91e51.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '3.5.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('85153c95-33dc-5303-8242-cdcf7391e087'::uuid, '0f230cb8-80fc-58f7-9526-e1a23b55bfb6'::uuid, 'Installation solaire 20kWc/20kW', 'Ce système PV de 20 kWc est raccordé à 2 onduleurs de 10 kW et est conçu pour l''autoconsommation. Points clés : - Objectif : consommation directe de l''énergie produite - Autonomie énergétique : 87% des besoins couverts - Economies Annuelles 32900 Dhs/An - Superficie utilisée sur le toit 90m²', '["https://lechantier.ma/uploads/media/814a373a8f75.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/814a373a8f75.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '3.5.3' LIMIT 1));
