INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('f326eb60-0410-563c-aa4b-f61ad273b28e'::uuid, 'b28becea-8ad5-52ce-8f4f-0eefa0f72c63'::uuid, 'Plan 3D studio', 'Un studio 3D de 50 m² est un espace moderne, compact et parfaitement optimisé 🏠✨📐 Il réunit coin nuit, salon, kitchenette et salle de bain dans un aménagement ouvert et harmonieux 🛏️🛋️🍳🚿 La visualisation 3D permet d’anticiper la lumière, la circulation et le choix du mobilier avant réalisation 💡🖥️📏 Idéal pour logements urbains, locations o', '["https://lechantier.ma/uploads/media/53786e103a3d.webp", "https://lechantier.ma/uploads/media/573309c3c54f.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/53786e103a3d.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '5.4.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('6dca1256-5ff8-5f82-af9d-82ce37a5f1d1'::uuid, 'b28becea-8ad5-52ce-8f4f-0eefa0f72c63'::uuid, 'Modèle de Patio ✨', 'Patio lumineux et authentique ✨💙 Un espace extérieur intime aux murs blancs éclatants, rehaussé de touches de bleu traditionnel et de zellige finement décoré. Les banquettes confortables, les plantes en pot et la lumière naturelle créent une ambiance paisible et fraîche, parfaite pour se détendre ou partager un moment convivial 🌿🪑.', '["https://lechantier.ma/uploads/media/f53bec9b84ab.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/f53bec9b84ab.webp', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '5.4.4' LIMIT 1));
