INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('9ad3d475-3b10-5972-977f-ad1656182f38'::uuid, 'c374dd0b-f2c9-5989-80db-63f95675b47f'::uuid, 'Bureau B308 -', 'Aménagement complet d’un espace de bureaux modernes avec intégration des systèmes d’éclairage intérieur, multimédia, occultants motorisés et solutions de sécurité. Résultat : Un environnement de travail confortable, connecté et sécurisé, offrant une meilleure efficacité énergétique et une gestion simplifiée grâce à la domotique centralisée.', '["https://lechantier.ma/uploads/media/6712159178bf.webp", "https://lechantier.ma/uploads/media/f2ea80b51486.webp", "https://lechantier.ma/uploads/media/31ededa9da03.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/6712159178bf.webp', 'Chock', (SELECT id FROM public.internal_categories WHERE code = '8.5.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('ea92e787-0c2c-5678-acbb-5ea8cbfdc294'::uuid, 'c374dd0b-f2c9-5989-80db-63f95675b47f'::uuid, 'Villa D721 - Domotique Lutron', 'Réalisation complète de l’installation électrique et intégration domotique Lutron pour la gestion de l’éclairage, des volets et de la climatisation. Mise en place d’un système de sonorisation multiroom haut de gamme. Résultat : Une villa élégante et connectée, où confort, design et technologie s’harmonisent.', '["https://lechantier.ma/uploads/media/3554cb5317c5.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/3554cb5317c5.webp', 'Chock', (SELECT id FROM public.internal_categories WHERE code = '8.5.3' LIMIT 1));
